    },
    {
      "kind": "other",
      "event_ids": ["A24"],
      "reason": "The final recommendation is truncated in the next action, and its 'would change if' conditions are internally inconsistent."
    },
    {
      "kind": "other",
      "event_ids": ["A1"],
      "reason": "The €20,000 / 12-week constraint does not appear in the case and is treated as an assumption."
    }
  ],
  "suitable_for_training": false,
  "screen_reason": "Unsuitable for training. A clipped and misread quote is used as support (A11), marketing copy is treated as demand evidence (A12, A17), the test design does not discriminate and has contradictory decision rules (A22), and the episode recommends investment on no supporting evidence, with a truncated and incoherent final recommendation (A24)."
